   "titolo": "Revolut Italia in amministrazione giudiziaria per riciclaggio aggravato",
   "orig": "Commissariata Banca Revolut: “Rapporti con indagati per riciclaggio aggravati dal metodo mafioso”",
   "lead": "La filiale italiana della banca digitale Revolut è stata posta sotto amministrazione giudiziaria dal Tribunale di Milano. Secondo l'inchiesta di Procura e Guardia di Finanza, la banca avrebbe avuto rapporti con indagati per riciclaggio aggravati dal metodo mafioso, con oltre un milione di violazioni scoperte e 76,5 milioni di euro che potevano essere intercettati. Tra i clienti coinvolti figurano Enrico Calamucci, legato all'agenzia di spionaggio Equalize, e un collaboratore di giustizia legato all'organizzazione Hydra.",
   "more": [
    "L'amministrazione giudiziaria è una misura di prevenzione che consente allo Stato di controllare temporaneamente un'azienda sospettata di favorire, anche involontariamente, attività illecite come il riciclaggio di denaro. Revolut è una fintech britannica con milioni di clienti anche in Italia, operante tramite licenza bancaria europea."
   ],
