   "titolo": "Proteste a Città del Capo per il trasferimento dei babbuini",
   "orig": "Relocation of Cape Town baboons to sanctuary ignites heated protests",
   "lead": "Il trasferimento di un branco di babbuini a Città del Capo verso un santuario per la fauna selvatica ha scatenato proteste tra i residenti locali, contrari alla loro cattura. Le autorità sostengono che l'operazione sia necessaria per prevenire conflitti tra uomini e primati in città. Il branco, composto da 44 esemplari noto come 'Waterfall troop' dal nome della zona in cui vive, è stato catturato venerdì nel quartiere costiero meridionale di Simon's Town. I manifestanti hanno cercato di bloccare il veicolo che trasportava gli animali. Lo riferisce The Guardian.",
