   "titolo": "Ahmad Tibi eletto vicepresidente della Knesset",
   "orig": "Who is Ahmad Tibi, the Arab MP elected deputy speaker of Israel’s Knesset?",
   "lead": "Il deputato arabo Ahmad Tibi è stato eletto vicepresidente della Knesset, il parlamento israeliano. Tibi, cittadino palestinese di Israele, è stato in passato consigliere di Yasser Arafat e siede come legislatore da 27 anni. La sua elezione rappresenta un passaggio significativo per la rappresentanza politica della minoranza araba in Israele. Lo riferisce Al Jazeera.",
   "more": [
    "La comunità arabo-israeliana costituisce circa il 20% della popolazione di Israele e dispone di propri partiti rappresentati alla Knesset, pur avendo storicamente un peso limitato nelle cariche istituzionali di alto profilo come quella di vicepresidente dell'assemblea."
   ],
