   "sez": "mondo",
   "titolo": "La Giordania vieta Telegram per motivi di sicurezza nazionale",
   "orig": "Jordan bans Telegram over national security concerns",
   "lead": "Le autorità giordane hanno vietato l'applicazione di messaggistica Telegram, citando preoccupazioni per la sicurezza nazionale. La misura arriva nel contesto di una stretta sulla sicurezza avviata dopo l'attacco mortale del mese scorso contro una chiesa greco-ortodossa. Lo riferisce Al Jazeera.",
   "more": [
    "La Giordania ha già in passato limitato l'accesso a piattaforme digitali durante periodi di tensione interna. Telegram è usata in diversi paesi mediorientali sia per comunicazioni private che per la diffusione di contenuti legati a gruppi estremisti, il che spinge talvolta i governi a restringerne l'uso."
   ],
