    "Depardieu, tra gli attori più noti del cinema francese, è stato accusato negli ultimi anni da diverse donne di comportamenti sessuali inappropriati sui set cinematografici. La condanna del 2025 ha segnato una tappa significativa nel dibattito pubblico francese sulle molestie nell'industria del cinema, alimentato anche dal movimento #MeToo."
