   "id": "z68d473cb",
   "sez": "prima",
   "titolo": "Burnham: 'Possibile un accordo win-win tra Regno Unito e UE'",
   "orig": "Burnham says 'win-win' deal can be agreed between UK and EU",
   "lead": "Il premier britannico Andy Burnham ha dichiarato che si può raggiungere un accordo 'vantaggioso per entrambi' tra Regno Unito e Unione Europea, più vicino a quello che gli elettori pensavano di votare nel referendum del 2016. Secondo il Financial Times, Burnham intende esporre le 'vesti nuove dell'imperatore' della Brexit davanti a un pubblico della City di Londra, dicendosi pronto a un confronto nazionale su un accordo di lungo periodo con l'Europa in vista del summit a Bruxelles di questa settimana. Boris Johnson ha criticato la svolta.",
   "more": [
    "La Brexit, l'uscita del Regno Unito dall'Unione Europea completata nel 2020, ha generato un acceso dibattito sui suoi effetti economici. Diversi studi hanno indicato perdite di crescita e maggiori ostacoli commerciali rispetto alla permanenza nell'UE, alimentando richieste di un riavvicinamento, pur restando politicamente sensibile riaprire la discussione sui termini dell'accordo originario."
   ],
