   "id": "z8d77d097",
   "sez": "prima",
   "titolo": "Capo Verde, José Maria Neves rieletto presidente con quasi due terzi dei voti",
   "orig": "Cape Verde election: Jose Maria Neves set to win second term",
   "lead": "Il presidente uscente di Capo Verde, José Maria Neves, è destinato a vincere un secondo mandato dopo aver ottenuto quasi i due terzi dei voti secondo i risultati provvisori. La sfidante Amado si è fermata al 31,6%. Neves ha definito la propria rielezione 'una grande vittoria', ringraziando i cittadini capoverdiani per la rinnovata fiducia e sottolineando una campagna basata sul confronto di idee. Lo riferisce Deutsche Welle, confermato da più testate locali e internazionali.",
   "more": [
    "Capo Verde, arcipelago dell'Africa occidentale, è considerato tra i paesi più stabili politicamente del continente, con elezioni regolari e alternanza democratica. Il presidente ha un ruolo prevalentemente rappresentativo e di garanzia istituzionale, mentre il governo è guidato dal primo ministro."
   ],
