   "sez": "salute",
   "titolo": "Il sonno influisce su aumento e perdita di peso, secondo gli studi",
   "orig": "Why sleep matters when it comes to weight gain and loss",
   "lead": "Secondo NPR, il sonno può avere un impatto significativo sul peso corporeo, influenzando l'appetito. La ricerca mostra anche una relazione a doppio senso tra qualità del sonno e alimentazione: dormire male può alterare le scelte alimentari, mentre una dieta scorretta può peggiorare il sonno. Lo riferisce NPR.",
   "more": [
    "Il sonno regola ormoni come la leptina e la grelina, che controllano rispettivamente senso di sazietà e fame. Una privazione cronica di sonno può quindi aumentare l'appetito e favorire scelte alimentari meno salutari, mentre un'alimentazione scorretta può a sua volta disturbare il riposo notturno."
   ],
