   "id": "zb445ab5c",
   "sez": "italia",
   "titolo": "La strategia di Schlein tra svolta radicale e rassicurazione",
   "orig": "Radicale ma rassicurante. Dietro la strategia di Schlein",
   "lead": "La segretaria del Partito Democratico Elly Schlein punta a una linea politica definita radicale ma al tempo stesso rassicurante per l'elettorato. L'obiettivo, secondo la ricostruzione di Repubblica, è convincere gli elettori che un cambiamento anche profondo nella proposta politica del Pd non equivale necessariamente a un salto nel buio. La scommessa riguarda la capacità di coniugare istanze di trasformazione con un'immagine di affidabilità, in un momento in cui il partito cerca di consolidare il proprio profilo identitario senza allontanare il bacino più moderato dell'elettorato. Lo riferisce la Repubblica.",
   "more": [
    "Dalla sua elezione a segretaria nel 2023, Elly Schlein ha spostato il baricentro del Partito Democratico su posizioni più marcate su temi sociali, ambientali e di diritti, cercando però di mantenere l'appeal verso l'elettorato moderato che tradizionalmente sostiene il centrosinistra italiano."
   ],
