   "id": "zbf48e140",
   "sez": "sport",
   "titolo": "Ronaldinho debutta con il Ravenna dopo 11 anni di stop",
   "orig": "Ronaldinho makes debut for Italian side Ravenna after 11-year hiatus in playing career",
   "lead": "L'ex fuoriclasse brasiliano Ronaldinho, 46 anni, ha giocato i primi 45 minuti della sua prima partita ufficiale dopo 11 anni di inattività, scendendo in campo con la maglia numero 10 del Ravenna, squadra di Serie C, nel derby contro il Forlì. L'ultima apparizione professionistica risaliva al Fluminense. Ronaldinho ha sfiorato il gol numero 300 in carriera senza riuscire a trovare la rete, ma ha contribuito al vantaggio della sua squadra. Presenti in campo anche altri ex calciatori come Dida e Serginho. Sugli spalti anche l'imprenditore Flavio Briatore.",
   "more": [
    "Ronaldinho, vincitore di un Mondiale con il Brasile nel 2002 e di due Palloni d'Oro, aveva chiuso ufficialmente la carriera con il Fluminense nel 2015. Il suo ritorno in campo a 46 anni, in Serie C italiana, rappresenta un evento mediatico più che sportivo, nell'ambito di operazioni di marketing legate al club romagnolo."
   ],
