   "id": "z883b6a75",
   "sez": "mondo",
   "titolo": "Operai in sciopero in Bangladesh chiudono fabbriche di abbigliamento",
   "orig": "Clothing factories shut in Bangladesh as workers strike over pay",
   "lead": "Numerose fabbriche di abbigliamento in Bangladesh hanno chiuso i battenti a causa di uno sciopero dei lavoratori, che chiedono un salario minimo di 30.000 taka (circa 182 sterline) al mese. La protesta coinvolge il settore tessile, pilastro dell'economia nazionale e tra i principali fornitori mondiali di abbigliamento a basso costo. Non sono specificate le risposte del governo o dei datori di lavoro alle richieste sindacali. Lo riferisce BBC News.",
   "more": [
    "Il Bangladesh è uno dei maggiori esportatori mondiali di abbigliamento, con un settore che impiega milioni di lavoratori, spesso a salari molto bassi rispetto al costo della vita. Le proteste per l'aumento del salario minimo sono ricorrenti e periodicamente portano a scioperi e chiusure temporanee degli stabilimenti produttivi."
   ],
