   "id": "zc0958a51",
   "sez": "cultura",
   "titolo": "Johnny Depp interpreta Scrooge in Ebenezer, nuovo adattamento di Dickens",
   "orig": "Ebenezer review – Johnny Depp’s Scrooge tries to exorcise ghosts of business past",
   "lead": "È uscito nelle sale 'Ebenezer', nuova versione cinematografica del classico di Charles Dickens 'A Christmas Carol', con Johnny Depp nei panni dell'avaro Ebenezer Scrooge. Il film, diretto da Ti West, ha debuttato al primo posto del box office con un incasso stimato di 42 milioni di dollari nel weekend di apertura. Secondo la recensione del Guardian, l'attore risulta più convincente nella parte del protagonista prima della sua redenzione che dopo. La pellicola segna il ritorno di Depp a Hollywood dopo le note vicende giudiziarie degli anni scorsi.",
   "more": [
    "'A Christmas Carol' di Charles Dickens, pubblicato nel 1843, racconta la trasformazione dell'avaro Ebenezer Scrooge dopo la visita di tre spiriti natalizi, ed è stato adattato innumerevoli volte al cinema e in televisione. Johnny Depp, celebre per ruoli come Jack Sparrow, era rimasto ai margini delle produzioni hollywoodiane dopo la causa legale con l'ex moglie Amber Heard."
   ],
