   "sez": "italia",
   "titolo": "Un nido di vespe orientali a 20 metri d'altezza a Roma, davanti al carcere di Rebibbia",
   "orig": "Vespa orientalis a Roma, nido a 20 metri d?altezza in un edificio di fronte al carcere di Rebibbia. «A novembre insetto ancora in piena attività»",
   "lead": "A Roma è stato individuato un nido di vespe orientali a circa 20 metri di altezza su un edificio di fronte al carcere di Rebibbia. Secondo il Messaggero, nonostante sia novembre l'insetto risulta ancora in piena attività nella capitale. La vespa orientale, considerata da alcuni sostanzialmente inoffensiva, genera invece per altri residenti una vera fobia, al punto da rendere difficile per alcuni affacciarsi sui propri balconi. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "La vespa orientale (Vespa orientalis) è una specie diffusa anche in area mediterranea, nota per costruire nidi di grandi dimensioni e per una maggiore tolleranza alle temperature elevate rispetto ad altre vespe, fattore che negli ultimi anni ne ha favorito la diffusione in contesti urbani anche nei mesi più freddi."
   ],
