   "orig": "Slovak companies are still profitable. But they are investing less in their future",
   "lead": "Un nuovo studio di KPMG rileva che le aziende slovacche continuano a essere profittevoli, ma la crescita dei ricavi sta rallentando e gli investimenti nel futuro restano debole. Il rapporto segnala una tendenza preoccupante per lo sviluppo economico del paese nei prossimi anni. Lo riferisce The Slovak Spectator.",
