   "lead": "Secondo quanto riportato dal Wall Street Journal e ripreso da Folha de S.Paulo, l'amministrazione di Donald Trump intende includere Nvidia in una lista di oltre 20 aziende statunitensi classificate come campioni nazionali, destinate a competere con rivali stranieri nei rispettivi settori. La notizia è stata diffusa domenica dal quotidiano economico americano. Lo riferisce Folha de S.Paulo.",
