    "Il concetto di 'campione nazionale' indica aziende sostenute dal governo per mantenere un vantaggio strategico in settori considerati cruciali, come i semiconduttori e l'intelligenza artificiale, in un contesto di crescente competizione tecnologica con la Cina."
