   "sez": "economia",
   "titolo": "Il debito pubblico italiano sale di 10,8 miliardi a settembre",
   "orig": "Bankitalia: +10,8mld di debito pubblico",
   "lead": "Secondo il bollettino di Bankitalia 'Finanza pubblica: fabbisogno e debito', a settembre il debito pubblico italiano è aumentato di 10,8 miliardi di euro, raggiungendo 3.211,6 miliardi. L'incremento è dovuto principalmente al debito delle amministrazioni centrali. Nei primi nove mesi dell'anno le entrate sono salite a 429,5 miliardi di euro, in crescita del 2,6%. La vita media residua del debito è aumentata a 7,9 anni.",
   "more": [
    "Il debito pubblico italiano è tra i più alti d'Europa in rapporto al PIL. Il suo andamento mensile, monitorato da Bankitalia, è un indicatore chiave per valutare la sostenibilità delle finanze pubbliche e influenza il giudizio dei mercati e delle agenzie di rating sul paese."
   ],
