   "orig": "UK’s Prince William, Princess Kate begin India visit with street cricket",
   "lead": "Il principe William e Kate Middleton hanno partecipato lunedì a una partita di cricket di strada a Mumbai, nel quartiere storico di Ballard Estate, insieme alla leggenda dello sport indiano Sachin Tendulkar. È il primo giorno di una visita di tre giorni, la più importante apparizione pubblica all'estero della principessa dopo le cure per un tumore nel 2024. Il viaggio comprende anche la cerimonia dell'Earthshot Prize. Lo riferiscono Daily Maverick, Sky News, ANSA e Sky TG24.",
