   "id": "zeb76f635",
   "sez": "mondo",
   "titolo": "Usa e Russia si opporranno ai negoziati sulla limitazione delle armi autonome",
   "orig": "U.S. and Russia to Oppose Talks on Limiting Autonomous Weapons",
   "lead": "Stati Uniti e Russia, principali produttori mondiali di armamenti, si preparano a opporsi, in un incontro globale a Ginevra, all'avvio di negoziati per regole vincolanti sulle armi autonome, note come 'killer robot'. Armi semi-autonome assistite dall'intelligenza artificiale sono già state impiegate in Ucraina, Sudan e Medio Oriente, nonostante le preoccupazioni etiche. Il segretario generale dell'Onu Antonio Guterres ha sottolineato come la natura della guerra stia cambiando. Lo riferiscono Moscow Times, Rappler e Cyprus Mail.",
   "more": [
    "Le armi autonome letali sono sistemi capaci di selezionare e colpire obiettivi senza intervento umano diretto. Da anni l'Onu discute di un possibile trattato vincolante per regolarne l'uso, ma i principali produttori di armamenti, tra cui Usa e Russia, hanno finora frenato il processo negoziale."
   ],
