   "id": "z6b314a1b",
   "sez": "economia",
   "titolo": "L'Ue dà il via libera all'acquisizione di Commerzbank da parte di UniCredit",
   "orig": "EU gibt UniCredit grünes Licht für Commerzbank-Übernahme",
   "lead": "La Commissione europea ha approvato l'acquisizione della banca tedesca Commerzbank da parte della banca italiana UniCredit, dichiarando di non avere 'preoccupazioni di natura concorrenziale'. UniCredit lavorava a questa operazione da due anni e l'approvazione di Bruxelles rappresenta un passo decisivo per la fusione tra i due istituti. Lo riferiscono Tagesschau, Der Spiegel, ORF e Euronews.",
   "more": [
    "L'operazione, se completata, darebbe vita a uno dei maggiori gruppi bancari transfrontalieri d'Europa, in un settore storicamente frammentato lungo linee nazionali; l'operazione è stata inizialmente contestata dal governo tedesco, preoccupato per il controllo straniero su una grande banca nazionale."
   ],
