   "id": "z934d6536",
   "sez": "mondo",
   "titolo": "Gugerotti in Terra Santa: \"Senza pace non c'è futuro per i cristiani\"",
   "orig": "Gugerotti in Terra Santa: \"Senza pace non c'è futuro per i cristiani\"",
   "lead": "Il cardinale Claudio Gugerotti, prefetto del Dicastero per le Chiese Orientali, sarà in visita in Israele e nei Territori palestinesi dal 16 al 21 novembre per portare la vicinanza e la benedizione di Papa Leone XIV alle comunità cristiane della regione. In un'intervista ai media vaticani, il porporato ha richiamato l'urgenza della pace per evitare il rischio di spopolamento delle comunità cristiane e ha sottolineato l'importanza della ripresa dei pellegrinaggi. Lo riferisce Vatican News.",
   "more": [
    "Le comunità cristiane in Terra Santa sono diminuite negli ultimi decenni per emigrazione, legata anche all'instabilità politica e ai conflitti nella regione; il turismo religioso e i pellegrinaggi rappresentano una delle principali fonti economiche per queste comunità."
   ],
