   "sez": "mondo",
   "titolo": "Kazakhstan, sostituito il capo della sicurezza dopo arresti per corruzione",
   "orig": "Kazakhstan Security Chief Replaced After High-Profile Corruption Arrests",
   "lead": "Il presidente kazako Kassym-Jomart Tokayev ha nominato Marat Irmenov come nuovo presidente del Comitato per la sicurezza nazionale (KNB), la principale agenzia di intelligence e sicurezza del paese, dopo una serie di arresti ad alto profilo per corruzione. Il predecessore era stato nominato durante le proteste del gennaio 2022. Le ragioni specifiche della decisione non sono state rese note. Lo riferiscono The Times of Central Asia, The Astana Times e Asia-Plus.",
   "more": [
    "Il KNB è l'agenzia di intelligence e sicurezza interna del Kazakhstan, erede dei servizi sovietici, ed è stato al centro di diverse epurazioni interne negli ultimi anni, in particolare dopo le violente proteste del gennaio 2022 che portarono a un giro di vite sulla dirigenza della sicurezza."
   ],
