   "orig": "Brasil avança em políticas de alimentação e clima, diz estudo",
   "lead": "Il Brasile ha aumentato la valutazione nel Food Systems NDC Scorecard da 6 a 8,5 su 12 tra 2025 e 2026 dopo aver pubblicato il Piano Clima, principale strumento per integrare i sistemi alimentari alla politica climatica nazionale. Lo riferisce Agência Brasil.",
